import math
L=2.75; L2=2.6; A=1.05
X=0.0; Y=0.0; YAW=0.0
MAP=set()
CELL=0.2
mode='rev'
taud=None
bay=None
lastp=-10.0
W=1.15

def w2(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def cl(v,lo,hi):
    return max(lo,min(hi,v))

def control(obs):
    global X,Y,YAW,mode,taud,bay,lastp
    dt=obs.get('dt',0.1) or 0.1
    m=obs['motion']; v=m['v_mps']; st=obs['steer_deg']
    X+=v*math.cos(YAW)*dt; Y+=v*math.sin(YAW)*dt
    YAW+=v*math.tan(math.radians(st))/L*dt
    c=math.cos(YAW); s=math.sin(YAW)
    def tw(px,py):
        return (X+px*c-py*s, Y+px*s+py*c)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        try:
            ox,oy=vw['origin']
            for p in vw.get('walls',[]) or []:
                b,d=p[0],p[1]
                br=math.radians(b)
                wx,wy=tw(ox+d*math.cos(br), oy+d*math.sin(br))
                MAP.add((int(round(wx/CELL)),int(round(wy/CELL))))
        except Exception:
            pass
    rig=obs['rig']
    tg=obs.get('target') or {}
    try:
        if tg.get('in_sight') and tg.get('dist_m') is not None:
            ex,ey=rig['eye']; br=math.radians(tg['bearing_deg']); d=tg['dist_m']
            bx,by=tw(ex+d*math.cos(br), ey+d*math.sin(br))
            if bay is None: bay=(bx,by)
            else: bay=(bay[0]*0.8+bx*0.2, bay[1]*0.8+by*0.2)
    except Exception:
        pass
    h=obs['hitch_deg']
    th=rig['trailer_heading_deg']
    trx,try_=tw(*rig['trailer_rear'])
    tau=w2(math.degrees(YAW)+th+180)
    # local points
    pts=[]
    for (i,j) in MAP:
        qx=i*CELL-trx; qy=j*CELL-try_
        if qx*qx+qy*qy<64: pts.append((qx,qy))
    baydir=None
    if bay is not None:
        baydir=math.degrees(math.atan2(bay[1]-try_, bay[0]-trx))
    best=None; bests=-1e9; bestfree=7.0; free0=7.0
    for off in range(-80,81,5):
        a=math.radians(tau+off); ca=math.cos(a); sa=math.sin(a)
        free=7.0
        for (qx,qy) in pts:
            al=qx*ca+qy*sa
            if al<-0.2: continue
            lat=abs(-qx*sa+qy*ca)
            if lat<W:
                f=al-math.sqrt(max(0.0,W*W-lat*lat))*0.5
                if f<free: free=f
        if off==0: free0=free
        sc=min(free,7.0)-0.015*abs(off)
        if baydir is not None:
            sc-=0.02*abs(w2(tau+off-baydir))
        if sc>bests:
            bests=sc; best=tau+off; bestfree=free
    if taud is None: taud=best
    taud=w2(taud+0.3*w2(best-taud))
    look=-23
    if mode=='rev' and abs(h)>42:
        mode='fwd'
    if mode=='fwd':
        if abs(h)<8:
            mode='rev'
        else:
            steer=cl(-1.5*h,-34,34)
            return (steer,0.8,look)
    e=w2(taud-tau)
    hdes=cl(-1.0*e,-35,35)
    hr=math.radians(h)
    deq=math.degrees(math.atan(L*math.sin(hr)/(L2+A*math.cos(hr))))
    steer=cl(deq+1.5*(h-hdes),-34,34)
    spd=-1.0
    if bestfree<2.5 or free0<2.0: spd=-0.6
    t=obs.get('t',0)
    if t-lastp>=2.0:
        lastp=t
        print('t%.1f tau%.0f taud%.0f h%.0f hd%.0f st%.0f free%.1f f0%.1f bay%s pts%d' % (t,tau,taud,h,hdes,steer,bestfree,free0,'Y' if bay else 'N',len(pts)))
    return (steer,spd,look)

