import math
pose=[0.0,0.0,0.0]
cells={}
last_t=None
phase='REV'
alpha_f=0.0
WB=2.5
lastprint=-10
tgt=None

def to_world(px,py):
    c=math.cos(pose[2]); s=math.sin(pose[2])
    return (pose[0]+c*px-s*py, pose[1]+s*px+c*py)

def clamp(x,a):
    return max(-a,min(a,x))

def control(obs):
    global last_t,phase,alpha_f,lastprint,tgt
    t=obs['t']
    v=obs['motion']['v_mps']; st=math.radians(obs['steer_deg'])
    if last_t is not None:
        d=t-last_t
        if 0<d<1:
            pose[0]+=v*math.cos(pose[2])*d
            pose[1]+=v*math.sin(pose[2])*d
            pose[2]+=v*math.tan(st)/WB*d
    last_t=t
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        o=vw.get('origin') or [0.75,0.0]
        for w in (vw.get('walls') or []):
            b=math.radians(w[0]); dd=w[1]
            px=o[0]+dd*math.cos(b); py=o[1]+dd*math.sin(b)
            wx,wy=to_world(px,py)
            cells[(int(math.floor(wx/0.3)),int(math.floor(wy/0.3)))]=(wx,wy,t)
    if len(cells)>1500 or int(t*10)%50==0:
        for k in [k for k,p in cells.items() if t-p[2]>40]:
            del cells[k]
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        b=math.radians(tg['bearing_deg']); dd=tg['dist_m']
        tgt=to_world(0.75+dd*math.cos(b), dd*math.sin(b))
    h=obs['hitch_deg']
    rig=obs['rig']; R=rig['trailer_rear']
    Rw=to_world(R[0],R[1])
    phi=math.radians(-h)
    angb=pose[2]+phi+math.pi
    rel=[]
    for p in cells.values():
        dx=p[0]-Rw[0]; dy=p[1]-Rw[1]
        if dx*dx+dy*dy<225: rel.append((dx,dy))
    at=None
    if tgt is not None:
        dx=tgt[0]-Rw[0]; dy=tgt[1]-Rw[1]
        dist=math.hypot(dx,dy)
        if dist<15:
            a=math.degrees(math.atan2(dy,dx)-angb)
            a=(a+180)%360-180
            at=a
    CAP=12.0; HW=1.6
    best=None; bests=-1e9
    for ai in range(-45,46,5):
        a=angb+math.radians(ai)
        c=math.cos(a); s=math.sin(a)
        free=CAP
        L=[]
        for dx,dy in rel:
            al=dx*c+dy*s; la=-dx*s+dy*c
            L.append((al,la))
            if 0<al<free and abs(la)<HW: free=al
        clear=3.0
        lim=min(free,8.0)
        for al,la in L:
            if -1.0<al<lim:
                if abs(la)<clear: clear=abs(la)
        sc=free+1.5*clear-0.02*abs(ai)
        if at is not None: sc-=0.04*abs(ai-at)
        if sc>bests: bests=sc; best=ai
    alpha_f+=0.3*(best-alpha_f)
    hdes=clamp(1.0*alpha_f,30)
    if phase=='REV' and abs(h)>48: phase='FWD'
    if phase=='FWD' and abs(h)<10: phase='REV'
    if phase=='FWD':
        steer=0.0; spd=0.8
    else:
        steer=clamp(0.5*h+1.5*(h-hdes),45)
        err=abs(h-hdes)
        spd=-0.9 if err<12 else -0.6
        if at is not None and tgt is not None and math.hypot(tgt[0]-Rw[0],tgt[1]-Rw[1])<5: spd=-0.6
    if t-lastprint>3:
        lastprint=t
        print('t%.0f ph%s h%.0f hd%.0f a%d st%.0f n%d at%s'%(t,phase,h,hdes,best,steer,len(rel),None if at is None else int(at)))
    return (steer,spd,170)

