        for k in [k for k,p in cells.items() if t-p[2]>40]:
            del cells[k]
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        b=math.radians(tg['bearing_deg']); dd=tg['dist_m']
        tgt=to_world(0.75+dd*math.cos(b), dd*math.sin(b))
    h=obs['hitch_deg']
    rig=obs['rig']; R=rig['trailer_rear']
    Rw=to_world(R[0],R[1])
