        if dx*dx+dy*dy<225: rel.append((dx,dy))
    at=None; tdist=None
    if tgt is not None:
        dx=tgt[0]-Rw[0]; dy=tgt[1]-Rw[1]
        tdist=math.hypot(dx,dy)
        a=math.degrees(math.atan2(dy,dx)-angb)
        at=(a+180)%360-180
    CAP=12.0; HW=1.6
    best=0; bests=-1e9; bestfree=CAP
    for ai in range(-45,46,5):
        a=angb+math.radians(ai)
