        clear=3.0
        lim=min(free,8.0)
        for al,la in L:
            if -1.0<al<lim:
                if abs(la)<clear: clear=abs(la)
        sc=free+1.5*clear-0.02*abs(ai)
        if at is not None and tdist is not None and tdist<15: sc-=0.06*abs(ai-at)
        if sc>bests: bests=sc; best=ai; bestfree=free
    alpha_f+=0.3*(best-alpha_f)
    hdes=clamp(-1.0*alpha_f,35)
    if tdist is not None and tdist<4: hdes=clamp(hdes,8)
    if phase=='FWD0':
        if fwd_d>1.6: phase='REV'
    if phase=='REV' and abs(h)>48: phase='FWD'
    if phase=='FWD' and abs(h)<10: phase='REV'
    if phase in ('FWD','FWD0'):
        steer=0.0; spd=0.8
    else:
        steer=clamp(0.5*h+1.5*(h-hdes),45)
        err=abs(h-hdes)
        spd=-0.9 if err<12 else -0.6
        if bestfree<2.0 or (tdist is not None and tdist<5): spd=-0.5
    if t-lastprint>3:
        lastprint=t
        print('t%.0f ph%s h%.0f hd%.0f a%d f%.1f st%.0f n%d at%s td%s'%(t,phase,h,hdes,best,bestfree,steer,len(rel),None if at is None else int(at),None if tdist is None else round(tdist,1)))
    return (steer,spd,gaze(t))

