            b=math.radians(w[0]); dd=w[1]
            px=o[0]+dd*math.cos(b); py=o[1]+dd*math.sin(b)
            a=(px-R[0])*f0+(py-R[1])*f1; lat=-(px-R[0])*f1+(py-R[1])*f0
            dT=math.hypot(max(-a,a-4.6,0.0),max(abs(lat)-thw,0.0))
            dV=math.hypot(max((vf-3.9)-px,px-vf,0.0),max(abs(py)-vhw,0.0))
