import math
seq=[-165,-125,-85,-45,-5,35,75,115,155,165]
idx=0
arr=None
pts=set()
cor=[]
done=False
def control(obs):
    global idx,arr,done
    t=obs['t']
    h=obs['head']
    views=obs.get('views') or {}
    for k,vw in views.items():
        if not vw: continue
        o=vw.get('origin',[0.1,0.0])
        for wp in vw.get('walls',[]) or []:
            if wp[1]>7.5: continue
            b=math.radians(wp[0]); d=wp[1]
            px=o[0]+d*math.cos(b); py=o[1]+d*math.sin(b)
            pts.add((round(px*4)/4,round(py*4)/4))
        for wp in vw.get('target_corners',[]) or []:
            b=math.radians(wp[0]); d=wp[1]
            cor.append((round(o[0]+d*math.cos(b),1),round(o[1]+d*math.sin(b),1)))
    if done:
        return (0.0,0.0,0)
    g=seq[idx]
    if abs(h['gaze_deg']-g)<2 and h.get('settled'):
        if arr is None: arr=t
        if t-arr>=0.25:
            idx+=1; arr=None
            if idx>=len(seq):
                done=True
                s=sorted(pts)
                print('PTS',' '.join('%g,%g'%p for p in s))
                print('BAY',cor[-8:])
                print('RIG',obs['rig']['hitch'],obs['rig']['trailer_rear'],'phi',obs['hitch_deg'],'tgt',obs.get('target'))
                wake('scan done')
                return (0.0,0.0,0)
            g=seq[idx]
    return (0.0,0.0,g)

