import math
n=0
mode='rev'
def control(obs):
    global n,mode
    n+=1
    phi=obs['hitch_deg']
    rig=obs['rig']; rx,ry=rig['trailer_rear']
    rem=obs['progress']['remaining']
    if mode=='halt': return (0.0,0.0,-165)
    yl=[];yr=[];back=9.0
    for k,vw in (obs.get('views') or {}).items():
        if not vw: continue
        o=vw.get('origin',[0.1,0.0])
        for wp in vw.get('walls',[]) or []:
            if wp[1]>3.0: continue
            b=math.radians(wp[0]); d=wp[1]
            px=o[0]+d*math.cos(b); py=o[1]+d*math.sin(b)
            if px<rx-0.05 and abs(py-ry)<0.55: back=min(back,rx-px)
            elif -2.5<px<0.5:
                if py>0.5: yl.append(py)
                elif py<-0.5: yr.append(py)
    off=0.0
    if yl and yr:
        off=ry-(min(yl)+max(yr))/2.0
    pd=max(-6,min(6,-8.0*off))
    sd=max(-30,min(30,pd+2.0*(phi-pd)))
    if rem<-0.9 or back<0.12:
        mode='halt'; print('stop rem',rem,'back',back); wake('stopped near end'); return (0.0,0.0,-165)
    if n%10==0: print(obs['t'],'rem',round(rem,2),'phi',round(phi,1),'off',round(off,2),'back',round(back,2),'sd',round(sd,1))
    return (sd,-0.2,-165)

